// The COMMAND-SURFACE node projection (`epic-command-surfaces-are-nodes`, slice 1) — turn the crate
// roster into Glance nodes and edges.
//
// The roster comes from `bsc surface crates --json`: every workspace member, whether it exposes verbs,
// the verbs it serves (joined from the one catalog), and its internal cargo dependencies. This module
// is the PURE projection of that into the graph vocabulary; fetching it is the caller's job.
//
// ONE NODE PER CRATE, INCLUDING THE ONES WITH NO VERBS. That is the 2026-09-01 decision and it is the
// whole reason the roster exists rather than just the catalog: the node's job is MAINTENANCE, and
// `bsc-util` exposes no verb while being the crate whose change reaches most of the workspace — so it
// is exactly the one that needs an owner. Whether a crate has verbs is a FACET on the node, never the
// criterion for having one.
import {
  surfaceNodeId,
  dependsOnEdgeId,
  verbNodeId,
  nounNodeId,
  verbOfEdgeId,
  type GRawNode,
  type GRawEdge,
  type GRole,
} from "@/features/glance/lib/glanceGraph";
import type { GlanceData } from "@/features/glance/lib/glanceData";

/** One row of `bsc surface crates --json`. */
export interface SurfaceRosterRow {
  /** The cargo PACKAGE name — the node key. Not the directory (`crates/data` is `bsc-data`) and not
   *  the lib target (`bsc-llm`'s is `llm`). */
  crate: string;
  /** The workspace member path, as the root Cargo.toml lists it. */
  path: string;
  /** Whether this crate exposes any `bsc` verb. A FACET — a false here still gets a node. */
  surface: boolean;
  /** The verbs it serves, in catalog order. Empty for a crate with no surface. */
  verbs: string[];
  /** Its internal cargo dependencies, by package name. */
  dependsOn: string[];
}

/** The projected band: one node per crate, one edge per internal dependency. */
export interface SurfaceGraph {
  nodes: GRawNode[];
  edges: GRawEdge[];
}

/** The three kinds of crate, by HOW YOU USE IT — the question a reader of this graph is asking. */
export type CrateKind = "surface" | "library" | "program";

/** Which accent each kind borrows. See {@link crateKind} for why these three and not others. */
export const CRATE_KIND_ROLE: Record<CrateKind, GRole> = {
  surface: "service", // something you CALL — `bsc <verb>`
  library: "infra",   // something others BUILD ON
  program: "client",  // something that RUNS on its own
};

/**
 * Classify one crate. Disjoint and exhaustive over the real roster: MEASURED 43 / 14 / 3 of 60.
 *
 * The axis is HOW THE CRATE IS USED, which is what a "kind" means here and what the graph is read for:
 *
 *  - `surface` — it answers `bsc <verb>`. The catalog says so, so this is a fact, not a heuristic.
 *  - `library` — no verb, but other crates depend on it. `bsc-util` is the extreme: no verb at all and
 *    44 dependents, which is exactly why the 2026-09-01 decision gave every crate a node.
 *  - `program` — no verb AND nothing depends on it: it is its own binary. `base-studio-code` (the app),
 *    `bsc-agent`, `bsc-hook`.
 *
 * FAN-IN IS THE DISCRIMINATOR between the last two, not a name pattern. `bsc-agent` and `bsc-hook` look
 * like libraries by name and are not; `channel` and `research` look like programs and are not. A name
 * heuristic would have got four of seventeen wrong, silently.
 */
export function crateKind(row: SurfaceRosterRow, fanIn: number): CrateKind {
  if (row.surface) return "surface";
  return fanIn > 0 ? "library" : "program";
}

/**
 * Project the crate roster into surface nodes + crate-dependency edges.
 *
 * `health` is `off` and `activity` is `idle` DELIBERATELY: a crate has no health signal yet. Marking
 * every crate `healthy` would assert something nobody measured, and this graph's whole point is that
 * the dot means something. Deriving real health (from `bsc errors`, or the gate) is a later
 * increment; until then the node says "no signal" rather than "fine".
 *
 * An edge to a crate that is NOT in the roster is DROPPED rather than drawn. A dangling edge is worse
 * than a missing one: the layout would carry a node id nothing renders, and the dependency count
 * shown on a node would include a target the user cannot click.
 */
export function surfaceGraph(roster: SurfaceRosterRow[]): SurfaceGraph {
  const known = new Set(roster.map((r) => r.crate));

  // How many OTHER crates build on each one — the signal that separates a library from a program.
  const fanIn = new Map<string, number>();
  for (const r of roster) {
    for (const dep of r.dependsOn) {
      if (dep !== r.crate && known.has(dep)) fanIn.set(dep, (fanIn.get(dep) ?? 0) + 1);
    }
  }

  const nodes: GRawNode[] = roster.map((r) => {
    const kind = crateKind(r, fanIn.get(r.crate) ?? 0);
    return {
      id: surfaceNodeId(r.crate),
      slug: r.crate,
      kind: "surface" as const,
      // The COLOUR channel. Not arbitrary: a library IS infrastructure others stand on, a surface IS a
      // service you call, and a program IS a client — the role vocabulary already means these things,
      // so a reader who knows the L1 legend is not learning a second code.
      role: CRATE_KIND_ROLE[kind],
      // The WORD channel, so the distinction survives colour-blindness, a greyscale screenshot and a
      // reader who has not memorised the legend. A colour alone is a cipher; a caption is a fact.
      roleLabel: kind,
      health: "off" as const,
      activity: "idle" as const,
    };
  });

  // TRANSITIVELY REDUCED — draw only the edges that are not already implied by a longer path.
  //
  // The full cargo graph is 230 edges over 60 crates and it made the drill LAG. Reachability is
  // identical either way: an edge A→C is dropped only when some A→B→…→C already exists, so nothing a
  // reader could follow is lost. MEASURED on the real roster: 230 → 123 edges (46% fewer), and the
  // hub collapse is the point — `bsc-util` went from 44 converging lines to 5, `bsc-cli-util` from
  // 46 to 19. Nearly every crate reaches `bsc-util` THROUGH `bsc-cli-util`, so 39 of those 44 lines
  // were restating a fact the graph already showed.
  //
  // A CAP was the alternative and is worse: dropping the Nth edge of a busy node hides a real
  // dependency and which one you lose depends on iteration order. A reduction is information-
  // preserving and deterministic. Safe because the graph is a DAG (cargo cannot express a cycle in
  // normal dependencies) — on a cyclic graph a transitive reduction is not unique.
  const adj = new Map<string, Set<string>>();
  for (const r of roster) {
    adj.set(r.crate, new Set(r.dependsOn.filter((d) => d !== r.crate && known.has(d))));
  }
  // Reachability per node, computed over a post-order so a node's successors are always done first.
  const reach = new Map<string, Set<string>>();
  const visiting = new Set<string>();
  const settle = (u: string): Set<string> => {
    const done = reach.get(u);
    if (done) return done;
    // `visiting` is belt-and-braces: the DAG is asserted by its own test, but a malformed roster must
    // not hang the cockpit. A back-edge simply contributes nothing rather than recursing forever.
    if (visiting.has(u)) return new Set();
    visiting.add(u);
    const acc = new Set<string>();
    for (const v of adj.get(u) ?? []) {
      acc.add(v);
      for (const w of settle(v)) acc.add(w);
    }
    visiting.delete(u);
    reach.set(u, acc);
    return acc;
  };
  for (const r of roster) settle(r.crate);

  const edges: GRawEdge[] = [];
  const seen = new Set<string>();
  for (const r of roster) {
    const deps = adj.get(r.crate) ?? new Set();
    for (const dep of deps) {
      // Implied by a sibling? Then the path already says it, and the line is noise.
      let implied = false;
      for (const other of deps) {
        if (other !== dep && reach.get(other)?.has(dep)) {
          implied = true;
          break;
        }
      }
      if (implied) continue;
      const id = dependsOnEdgeId(r.crate, dep);
      if (seen.has(id)) continue;
      seen.add(id);
      edges.push({ id, from: surfaceNodeId(r.crate), to: surfaceNodeId(dep), kind: "depends-on" });
    }
  }
  return { nodes, edges };
}

// `dependentCount` USED TO LIVE HERE. Rust owns it: `bsc surface drill` computes
// `"dependentCount": dependents.len()` (crates/bsc/src/main.rs) and ships it as a field on
// `CrateDrillDoc`, so the TypeScript copy answered the same question a second time and was called by
// nothing but its own test. `glanceFoldsAreCalled.test.ts` found it the moment that guard stopped
// counting a generated copy of a declaration as a call site.
/**
 * Fold the crate roster into a DRILL's graph — the app's own project drill, beside its studio sessions.
 *
 * NOT AN L0 BAND, AND THAT IS THE WHOLE POINT. `glanceData` carries the epitaph of the first attempt:
 * one node per active `bsc` subcommand and no edge at all, because the `invokes` edge runs
 * session→surface and L0 has no session node to draw one from. It left 33 permanently unconnected
 * nodes beside the project network — an inventory of the CLI rendered as if it were part of the
 * project graph. The `surfaces` parameter was deleted rather than kept and ignored, precisely so a
 * later reader would not put it back.
 *
 * Two things make this different rather than a repeat, and both are the 2026-09-01 decisions:
 * the node is keyed on the CRATE (so `bsc-util`, which has no verb and reaches 40 crates, gets one),
 * and the band HAS EDGES — `depends-on`, derived from cargo metadata. Structure is exactly what the
 * removed band lacked.
 *
 * Returns `data` UNCHANGED on an empty roster. A failed read must leave what is already drawn alone:
 * blanking the band on a transient error would make every crate vanish from the cockpit, which is the
 * rule the integration band states for the same reason.
 */
export function withSurfaceNodes(data: GlanceData, roster: SurfaceRosterRow[]): GlanceData {
  if (!roster.length) return data;
  const { nodes, edges } = surfaceGraph(roster);
  const present = new Set(data.rawNodes.map((n) => n.id));

  // EVERY CRATE CARRIES ITS REPO, or the drill stops separating by repository.
  //
  // `bandNodesByRepo` groups a drill's nodes on `n.repo` and leaves anything without one UNGROUPED —
  // so crates with no repo scattered through the whole graph instead of sitting with the repository
  // they live in. That was a regression the moment these stopped being fenced band nodes, because the
  // fence had been doing the separating by accident.
  //
  // The repo is taken from the nodes ALREADY in this drill rather than passed in: those are the
  // streams, and `withStreamRepos` has already stamped each with the repo from the plan — so a crate
  // joins the same band as the streams that own it, spelled exactly the same way. A roster is ONE
  // cargo workspace, hence one repository, which is why a single modal value is correct here and not
  // a simplification.
  //
  // With no repo to be had (a drill whose streams carry none) the crates are left UNSTAMPED rather
  // than given an invented one — ungrouped is honest, a wrong band is not.
  const repoTally = new Map<string, number>();
  for (const n of data.rawNodes) {
    if (n.repo) repoTally.set(n.repo, (repoTally.get(n.repo) ?? 0) + 1);
  }
  let repo: string | undefined;
  let best = 0;
  for (const [r, count] of repoTally) {
    if (count > best) {
      best = count;
      repo = r;
    }
  }

  const add = nodes.filter((n) => !present.has(n.id)).map((n) => (repo ? { ...n, repo } : n));
  if (!add.length) return data;
  // Every id this drill will hold once `add` lands — an edge is kept only if BOTH ends resolve, so a
  // node already drawn under another kind cannot acquire a dangling dependency line.
  const known = new Set([...present, ...add.map((n) => n.id)]);
  const seen = new Set(data.rawEdges.map((e) => e.id));
  const addEdges = edges.filter(
    (e) => !seen.has(e.id) && known.has(e.from) && known.has(e.to),
  );
  return { ...data, rawNodes: [...data.rawNodes, ...add], rawEdges: [...data.rawEdges, ...addEdges] };
}
/** One noun's row in `bsc surface drill <crate> --json`. */
export interface CrateDrillNoun {
  noun: string;
  status: string;
  catalog: "projected" | "unreachable";
  /** NULL when the crate serves this noun but publishes no `CmdDoc` catalog — distinct from empty. */
  verbs: { verb: string; summary: string; usage: string }[] | null;
}

/** The whole of `bsc surface drill <crate> --json`. */
export interface CrateDrillDoc {
  crate: string;
  path: string;
  surface: boolean;
  nouns: CrateDrillNoun[];
  dependsOn: string[];
  dependents: string[];
  dependentCount: number;
}

/**
 * THE SECOND LAYER — the NOUNS a crate serves, each rooting its own verbs.
 *
 * MAINTAINER 2026-09-02: "we should have the noun as the root of these graphs." The first cut rooted
 * the CRATE and hung every verb off it, which flattened `logs`/`metrics`/`perf` into one fan and lost
 * the thing a reader is actually navigating — you run `bsc logs sessions`, not `bsc logs-crate
 * sessions`. The noun IS the command; the crate is where it happens to be implemented.
 *
 * So a multi-noun crate yields a FOREST, one root per noun. That is the honest shape: those really are
 * three separate commands that happen to share a compilation unit.
 *
 * A NOUN WITH NO REACHABLE CATALOG IS STILL DRAWN, and this reverses the first cut deliberately.
 * Rooted on the crate, an empty cluster asserted the crate offered something it did not. Rooted on the
 * noun, the node says `bsc metrics` EXISTS and has no verb catalog — which is true and is exactly what
 * a reader wanting to know what they can run needs to see. It is captioned so the emptiness reads as a
 * fact rather than as a load that failed.
 *
 * A crate with NO nouns at all — a library or a program — yields just its own node, so the layer never
 * renders blank, which would read as a failed load rather than as "nothing to call here".
 */
export function crateDrillGraph(doc: CrateDrillDoc): GlanceData {
  const kind = crateKind(
    { crate: doc.crate, path: doc.path, surface: doc.surface, verbs: [], dependsOn: doc.dependsOn },
    doc.dependentCount,
  );
  const rawNodes: GRawNode[] = [];
  const rawEdges: GRawEdge[] = [];

  for (const noun of doc.nouns) {
    const rootId = nounNodeId(noun.noun);
    rawNodes.push({
      id: rootId,
      slug: noun.noun,
      kind: "surface" as const,
      role: CRATE_KIND_ROLE.surface,
      // The caption names the CRATE, so a reader knows where this command lives without leaving the
      // layer — the fact the crate root used to carry, kept where it is still useful.
      roleLabel: doc.crate,
      health: "off" as const,
      activity: "idle" as const,
    });

    for (const v of noun.verbs ?? []) {
      const id = verbNodeId(noun.noun, v.verb);
      if (rawNodes.some((x) => x.id === id)) continue;
      rawNodes.push({
        id,
        slug: v.verb,
        kind: "surface" as const,
        role: CRATE_KIND_ROLE.surface,
        // Its NOUN, which is what tells `bsc logs summary` from `bsc perf summary`.
        roleLabel: noun.noun,
        health: "off" as const,
        activity: "idle" as const,
      });
      // VERB → NOUN, and the direction is the LAYOUT. The engine lays layers left→right and puts
      // whatever an edge points AT on the left, so `noun → verb` placed each verb to the LEFT of its
      // own noun — backwards for a left-to-right reader. Pointing the verb AT its noun puts the noun
      // on the left with its verbs fanning right, which is the reading order.
      rawEdges.push({
        id: verbOfEdgeId(doc.crate, noun.noun, v.verb),
        from: id,
        to: rootId,
        kind: "verb-of",
      });
    }
  }

  // Nothing to call: show the crate itself rather than an empty canvas.
  if (!rawNodes.length) {
    rawNodes.push({
      id: surfaceNodeId(doc.crate),
      slug: doc.crate,
      kind: "surface" as const,
      role: CRATE_KIND_ROLE[kind],
      roleLabel: kind,
      health: "off" as const,
      activity: "idle" as const,
    });
  }
  return { rawNodes, rawEdges, sample: false };
}
